INSERT INTO DeliveryAssignment (order_id,drone_id,pilot_id,status) SELECT o.order_id,d.drone_id,p.pilot_id,'Assigned' FROM DeliveryOrder o JOIN Drone d ON d.model='Delivery-X1' JOIN Pilot p ON p.phone='9876500004' WHERE o.delivery_address='Malviya Nagar, Jaipur' AND NOT EXISTS (SELECT 1 FROM DeliveryAssignment a WHERE a.order_id=o.order_id);
INSERT INTO Maintenance (drone_id,service_date,description,cost) SELECT d.drone_id,'2026-10-15','Battery replacement',3500 FROM Drone d WHERE d.model='Delivery-X3' AND NOT EXISTS (SELECT 1 FROM Maintenance m WHERE m.drone_id=d.drone_id AND m.service_date='2026-10-15' AND m.description='Battery replacement');
